(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u001-btn');
  var mag = root.querySelector('.u001-mag');
  var live = root.querySelector('.u001-live');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var timers = [];
  function later(fn, ms) { timers.push(setTimeout(function () { if (root.isConnected) fn(); }, ms)); }
  function clear() { timers.forEach(clearTimeout); timers = []; }

  // 커서가 가까워지면 버튼이 살짝 끌려오고, 빛 반사가 커서를 따라갑니다
  root.addEventListener('pointermove', function (e) {
    var r = btn.getBoundingClientRect();
    var dx = e.clientX - (r.left + r.width / 2);
    var dy = e.clientY - (r.top + r.height / 2);
    var pull = rm ? 0 : Math.max(0, 1 - Math.hypot(dx, dy) / 190);
    mag.style.translate = (dx * 0.18 * pull).toFixed(1) + 'px ' + (dy * 0.18 * pull).toFixed(1) + 'px';
    btn.style.setProperty('--mx', ((e.clientX - r.left) / r.width * 100).toFixed(1) + '%');
    btn.style.setProperty('--my', ((e.clientY - r.top) / r.height * 100).toFixed(1) + '%');
  });
  root.addEventListener('pointerleave', function () { mag.style.translate = '0px 0px'; });

  // 누르면: 물방울 로딩 → 완료 체크로 펼쳐짐 → 원래 버튼으로 복귀
  btn.addEventListener('click', function () {
    if (root.dataset.state === 'load') return;
    clear();
    root.dataset.state = 'load';
    btn.setAttribute('aria-busy', 'true');
    live.textContent = '저장하는 중';
    later(function () {
      root.dataset.state = 'ok';
      btn.removeAttribute('aria-busy');
      live.textContent = '저장했어요';
    }, rm ? 200 : 1600);
    later(function () { root.dataset.state = 'idle'; live.textContent = ''; }, rm ? 1200 : 3600);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u002-btn');
  var mag = root.querySelector('.u002-mag');
  var txt = root.querySelector('.u002-txt');
  var orb = root.querySelector('.u002-orb');
  var live = root.querySelector('.u002-live');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var t = 0;

  // 버튼 전체, 글자, 화살표 원이 서로 다른 깊이로 커서를 따라옵니다
  root.addEventListener('pointermove', function (e) {
    if (rm) return;
    var r = btn.getBoundingClientRect();
    var dx = e.clientX - (r.left + r.width / 2);
    var dy = e.clientY - (r.top + r.height / 2);
    var p = Math.max(0, 1 - Math.hypot(dx, dy) / 240);
    mag.style.translate = (dx * 0.12 * p).toFixed(1) + 'px ' + (dy * 0.22 * p).toFixed(1) + 'px';
    txt.style.translate = (dx * 0.05 * p).toFixed(1) + 'px ' + (dy * 0.08 * p).toFixed(1) + 'px';
    orb.style.translate = (dx * 0.1 * p).toFixed(1) + 'px ' + (dy * 0.14 * p).toFixed(1) + 'px';
  });
  root.addEventListener('pointerleave', function () {
    mag.style.translate = txt.style.translate = orb.style.translate = '0px 0px';
  });

  // 누르면 화살표가 빠져나갔다 돌아오고, 문구가 굴러 바뀐 뒤 원래대로 돌아옵니다
  btn.addEventListener('click', function () {
    clearTimeout(t);
    root.dataset.state = 'idle';
    void btn.offsetWidth;
    root.dataset.state = 'go';
    live.textContent = '준비됐어요';
    t = setTimeout(function () { if (root.isConnected) { root.dataset.state = 'idle'; live.textContent = ''; } }, rm ? 900 : 1900);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u003-btn');
  var file = root.querySelector('.u003-file');
  var done = root.querySelector('.u003-done');
  var undo = root.querySelector('.u003-undo');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var HOLD = 1200;
  var p = 0, raf = 0, last = 0, holding = false, finished = false;

  function set(v) { p = v; btn.style.setProperty('--p', v.toFixed(4)); }
  // 누르는 동안 채움이 차오르고, 손을 떼면 같은 속도의 두 배로 빠지며 돌아갑니다
  function tick(now) {
    if (!root.isConnected) return;
    var dt = now - (last || now);
    last = now;
    if (holding) set(Math.min(1, p + dt / HOLD));
    else set(Math.max(0, p - dt / (HOLD / 2.4)));
    btn.style.setProperty('--shake', holding && p > 0.55 && !rm ? 'running' : 'paused');
    if (p >= 1 && holding) { complete(); return; }
    if (holding || p > 0) raf = requestAnimationFrame(tick);
    else { raf = 0; last = 0; }
  }
  function start() {
    if (finished) return;
    holding = true;
    btn.classList.add('is-holding');
    if (!raf) { last = 0; raf = requestAnimationFrame(tick); }
  }
  function stop() {
    holding = false;
    btn.classList.remove('is-holding');
    if (!raf && p > 0) raf = requestAnimationFrame(tick);
  }
  function complete() {
    holding = false; finished = true; raf = 0; last = 0;
    btn.classList.remove('is-holding');
    file.classList.add('is-gone');
    btn.classList.add('is-gone');
    btn.setAttribute('tabindex', '-1');
    done.classList.add('is-on');
    undo.focus({ preventScroll: true });
  }
  function restore() {
    finished = false;
    set(0);
    file.classList.remove('is-gone');
    btn.classList.remove('is-gone');
    btn.removeAttribute('tabindex');
    done.classList.remove('is-on');
    btn.focus({ preventScroll: true });
  }
  btn.addEventListener('pointerdown', function (e) { if (e.button === 0) { btn.setPointerCapture(e.pointerId); start(); } });
  btn.addEventListener('pointerup', stop);
  btn.addEventListener('pointercancel', stop);
  btn.addEventListener('lostpointercapture', stop);
  btn.addEventListener('contextmenu', function (e) { e.preventDefault(); });
  // 키보드는 Space나 Enter를 누르고 있는 동안 차오릅니다
  btn.addEventListener('keydown', function (e) {
    if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); if (!e.repeat) start(); }
  });
  btn.addEventListener('keyup', function (e) { if (e.key === ' ' || e.key === 'Enter') stop(); });
  btn.addEventListener('blur', stop);
  btn.addEventListener('click', function (e) { e.preventDefault(); });
  undo.addEventListener('click', restore);
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u004-btn');
  var pct = root.querySelector('.u004-pct');
  var eta = root.querySelector('.u004-eta');
  var live = root.querySelector('.u004-live');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var raf = 0, timers = [], p = 0, t0 = 0, DUR = rm ? 600 : 3200;
  function later(fn, ms) { timers.push(setTimeout(function () { if (root.isConnected) fn(); }, ms)); }
  function clear() { timers.forEach(clearTimeout); timers = []; cancelAnimationFrame(raf); raf = 0; }
  function set(v) {
    p = v;
    btn.style.setProperty('--p', v.toFixed(4));
    pct.textContent = Math.round(v * 100) + '%';
  }
  // 실제 네트워크처럼 빨라졌다 느려졌다 하는 진행 곡선입니다
  function curve(x) { return Math.min(1, x + Math.sin(x * Math.PI * 3) * 0.045 * (1 - x)); }
  function step(now) {
    if (!root.isConnected) return;
    var x = Math.min(1, (now - t0) / DUR);
    set(curve(x));
    var left = Math.max(0, Math.ceil((1 - x) * DUR / 1000 * 2.2));
    eta.textContent = left > 0 ? '남은 시간 ' + left + '초' : '마무리하는 중';
    if (x < 1) raf = requestAnimationFrame(step);
    else finish();
  }
  function finish() {
    root.dataset.state = 'fold';
    live.textContent = '다운로드 완료';
    later(function () { root.dataset.state = 'done'; }, rm ? 100 : 650);
    later(reset, rm ? 1600 : 3400);
  }
  function reset() { clear(); root.dataset.state = 'idle'; set(0); live.textContent = ''; }
  btn.addEventListener('click', function () {
    var s = root.dataset.state;
    if (s === 'run') { // 받는 중에 누르면 취소하고 처음으로 돌아갑니다
      clear();
      root.dataset.state = 'idle';
      set(0);
      live.textContent = '다운로드를 취소했어요';
      return;
    }
    if (s !== 'idle') { reset(); return; }
    clear();
    set(0);
    root.dataset.state = 'run';
    live.textContent = '다운로드 시작';
    later(function () { t0 = performance.now(); raf = requestAnimationFrame(step); }, rm ? 0 : 260);
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u005-btn'), inp = root.querySelector('.u005-in'), th = root.querySelector('.u005-th'), cp = root.querySelector('.u005-cp');
  var tr = root.querySelector('.u005-tr'), mk = root.querySelector('.u005-mk');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var NEXT = ['방금 찍은 사진 보낼게요 📷', '내일 10시에 만나요!', '고마워요, 덕분에 살았어요 🙏'];
  var PLANE = '<svg viewBox="0 0 28 24"><path d="M1 3 27 12 10 13Z" fill="#fff"/><path d="M10 13 27 12 6 22Z" fill="#D8E0FF"/><path d="M10 13 27 12 12.5 17Z" fill="#A3B4FF"/><path d="M1 3 27 12 10 13Z" fill="none" stroke="#7B61FF" stroke-width=".8" stroke-linejoin="round"/><path d="M10 13 27 12 6 22Z" fill="none" stroke="#7B61FF" stroke-width=".8" stroke-linejoin="round"/></svg>';
  // 같은 요소가 한 화면에 둘 이상 있어도 꼬리 마스크가 섞이지 않게 아이디를 따로 붙입니다
  var mid = 'u005-m' + Math.random().toString(36).slice(2, 8);
  root.querySelector('mask').id = mid; tr.setAttribute('mask', 'url(#' + mid + ')');
  var n = 0, busy = false;
  inp.value = NEXT[0];
  var canPath = window.CSS && CSS.supports && CSS.supports('offset-path', 'path("M0 0L1 1")');
  // 버튼 가운데에서 떠올라 왼쪽 위로 크게 고리를 한 바퀴 돈 뒤, 오른쪽 위 화면 밖으로 빠져나가는 길
  function route() {
    var b = btn.getBoundingClientRect(), r = root.getBoundingClientRect(), k = root.offsetWidth / (r.width || 1);
    var x = (b.left - r.left + b.width / 2) * k, y = (b.top - r.top + b.height / 2) * k;
    return 'M' + x + ' ' + y + ' C' + (x - 30) + ' ' + (y - 60) + ' ' + (x - 150) + ' ' + (y - 70) + ' ' + (x - 150) + ' ' + (y - 140) +
      ' C' + (x - 150) + ' ' + (y - 205) + ' ' + (x - 70) + ' ' + (y - 215) + ' ' + (x - 60) + ' ' + (y - 165) +
      ' C' + (x - 50) + ' ' + (y - 120) + ' ' + (x - 125) + ' ' + (y - 110) + ' ' + (x - 120) + ' ' + (y - 170) +
      ' C' + (x - 115) + ' ' + (y - 235) + ' ' + (x - 10) + ' ' + (y - 280) + ' ' + (x + 90) + ' ' + (y - 330);
  }
  function bubble(text) {
    var b = document.createElement('div'); b.className = 'u005-bb out' + (rm ? '' : ' pop'); b.textContent = text;
    var st = document.createElement('div'); st.className = 'u005-st'; st.innerHTML = '<span></span><svg viewBox="0 0 16 10" aria-hidden="true"><path d="M1 5.5 4 8.5 9.5 2M7 8.5 15 1"/></svg>';
    st.firstChild.textContent = '보내는 중';
    th.appendChild(b); th.appendChild(st);
    // 대화가 넘치면 가장 오래된 말풍선부터 치웁니다
    while (th.children.length > 5) th.removeChild(th.firstChild);
    return st;
  }
  function send() {
    var text = inp.value.trim();
    if (busy) return;
    if (!text) { cp.classList.remove('shake'); void cp.offsetWidth; cp.classList.add('shake'); inp.focus(); return; }
    busy = true;
    var st = bubble(text);
    inp.value = '';
    var d = route(), dur = rm ? 0 : 1500;
    btn.classList.remove('back', 'done');
    btn.classList.add('fly');
    if (!rm) {
      tr.setAttribute('d', d); mk.setAttribute('d', d); tr.style.opacity = '';
      var fp = document.createElement('div'); fp.className = 'u005-fp'; fp.innerHTML = PLANE;
      root.appendChild(fp);
      var ease = 'cubic-bezier(.45,0,.3,1)';
      if (canPath && fp.animate) {
        fp.style.offsetPath = 'path("' + d + '")'; fp.style.offsetRotate = 'auto';
        fp.animate([{ offsetDistance: '0%', transform: 'scale(.75)' }, { offsetDistance: '35%', transform: 'scale(1.25)', offset: 0.35 }, { offsetDistance: '100%', transform: 'scale(.7)' }], { duration: dur, easing: ease, fill: 'forwards' });
      } else if (fp.animate) {
        var p = d.split(/[ MC]+/).filter(Boolean).map(Number);
        fp.animate([{ transform: 'translate(' + (p[0] - 17) + 'px,' + (p[1] - 15) + 'px)' }, { transform: 'translate(' + (p[p.length - 2] - 17) + 'px,' + (p[p.length - 1] - 15) + 'px) rotate(-40deg)' }], { duration: dur, easing: ease, fill: 'forwards' });
      }
      if (mk.animate) mk.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: dur, easing: ease, fill: 'forwards' });
      setTimeout(function () { fp.remove(); tr.style.opacity = '0'; }, dur + 80);
    }
    setTimeout(function () {
      btn.classList.remove('fly'); btn.classList.add('done');
      st.firstChild.textContent = '전송됨'; st.classList.add('ok');
    }, dur ? dur - 100 : 0);
    setTimeout(function () {
      if (!root.isConnected) return;
      btn.classList.remove('done'); btn.classList.add('back');
      n = (n + 1) % NEXT.length; inp.value = NEXT[n];
      busy = false;
    }, rm ? 0 : dur + 900);
  }
  btn.addEventListener('click', send);
  inp.addEventListener('keydown', function (e) { if (e.key === 'Enter' && !e.isComposing) { e.preventDefault(); send(); } });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u006-btn');
  var roll = root.querySelector('.u006-roll');
  var sr = root.querySelector('.u006-sr');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var count = 1284;
  var on = false;
  var fmt = function (n) { return n.toLocaleString('ko-KR'); };

  // 구독자 수가 위(늘 때) 또는 아래(줄 때)로 한 칸 굴러갑니다
  var curIdx = 0;
  function rollTo(n, up) {
    var cur = roll.children[curIdx], nxt = roll.children[1 - curIdx];
    nxt.style.transition = 'none';
    nxt.textContent = fmt(n);
    nxt.style.transform = 'translateY(' + (up ? 100 : -100) + '%)';
    nxt.style.opacity = '0';
    void nxt.offsetWidth;
    nxt.style.transition = '';
    nxt.style.transform = 'none';
    nxt.style.opacity = '1';
    cur.style.transform = 'translateY(' + (up ? -100 : 100) + '%)';
    cur.style.opacity = '0';
    curIdx = 1 - curIdx;
  }
  // 누른 자리에서 다음 상태의 색이 원으로 번집니다
  function ripple(x, y) {
    if (rm) return;
    var r = btn.getBoundingClientRect();
    var k = r.width / btn.offsetWidth || 1;
    var px = (x - r.left) / k, py = (y - r.top) / k;
    var w = btn.offsetWidth, h = btn.offsetHeight;
    var far = Math.hypot(Math.max(px, w - px), Math.max(py, h - py));
    var ink = document.createElement('span');
    ink.className = 'u006-ink';
    ink.style.left = px + 'px';
    ink.style.top = py + 'px';
    ink.style.setProperty('--s', (far / 10 + 0.4).toFixed(2));
    ink.style.setProperty('--c', on ? 'var(--ux-danger)' : 'var(--ux-surface)');
    btn.appendChild(ink);
    setTimeout(function () { ink.remove(); }, 900);
  }
  btn.addEventListener('click', function (e) {
    var x = e.clientX, y = e.clientY;
    if (!e.detail) { var r = btn.getBoundingClientRect(); x = r.left + r.width / 2; y = r.top + r.height / 2; }
    ripple(x, y);
    on = !on;
    count += on ? 1 : -1;
    root.classList.toggle('is-on', on);
    btn.setAttribute('aria-pressed', String(on));
    rollTo(count, on);
    sr.textContent = on ? '구독했어요. 구독자 ' + fmt(count) + '명' : '구독을 취소했어요';
  });
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u007-btn');
  var L = root.querySelector('.u007-l'), R = root.querySelector('.u007-r');
  var wave = root.querySelector('.u007-wave');
  var nowEl = root.querySelector('.u007-now');
  var rm = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  // 그라디언트 id가 여러 개 생겨도 겹치지 않게 이 요소만의 id를 붙입니다
  var gid = 'u007-g-' + Math.random().toString(36).slice(2, 7);
  root.querySelector('linearGradient').id = gid;
  root.querySelector('.u007-arc').style.stroke = 'url(#' + gid + ')';

  // 삼각형을 두 조각으로 나눠, 각 꼭짓점을 일시정지 막대의 꼭짓점으로 옮깁니다
  var PLAY = [[[13, 8], [22.5, 13.6], [22.5, 26.4], [13, 32]], [[22.5, 13.6], [32, 20], [32, 20], [22.5, 26.4]]];
  var PAUSE = [[[11, 9], [17, 9], [17, 31], [11, 31]], [[23, 9], [29, 9], [29, 31], [23, 31]]];
  var shape = 0, raf = 0;
  function draw(t) {
    [L, R].forEach(function (poly, k) {
      poly.setAttribute('points', PLAY[k].map(function (p, j) {
        var q = PAUSE[k][j];
        return (p[0] + (q[0] - p[0]) * t).toFixed(2) + ',' + (p[1] + (q[1] - p[1]) * t).toFixed(2);
      }).join(' '));
    });
  }
  function morph(to) {
    cancelAnimationFrame(raf);
    var from = shape, t0 = performance.now(), D = rm ? 1 : 420;
    (function f(now) {
      var x = Math.min(1, (now - t0) / D);
      var e = 1 + 2.2 * Math.pow(x - 1, 3) + 1.2 * Math.pow(x - 1, 2); // 살짝 넘쳤다 돌아오는 곡선
      shape = from + (to - from) * e;
      draw(shape);
      if (x < 1) raf = requestAnimationFrame(f);
    })(t0);
  }
  draw(0);

  // 파형 막대 44개. 재생한 구간만 색이 찹니다
  var N = 44, bars = [];
  for (var i = 0; i < N; i++) {
    var b = document.createElement('i');
    var h = 30 + Math.abs(Math.sin(i * 0.9) * 46 + Math.sin(i * 0.37) * 24);
    b.style.setProperty('--h', Math.min(100, h).toFixed(0));
    b.style.setProperty('--d', (i % 7) / 7);
    wave.appendChild(b);
    bars.push(b);
  }
  var TOTAL = 220, pos = 72, playing = false, last = 0, loop = 0;
  function fmt(s) { s = Math.floor(s); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); }
  function render() {
    var p = pos / TOTAL;
    root.style.setProperty('--p', p.toFixed(4));
    var on = Math.round(p * N);
    bars.forEach(function (b, k) { b.classList.toggle('on', k < on); });
    nowEl.textContent = fmt(pos);
    wave.setAttribute('aria-valuenow', String(Math.floor(pos)));
    wave.setAttribute('aria-valuetext', Math.floor(pos / 60) + '분 ' + Math.floor(pos % 60) + '초');
  }
  function tick(now) {
    if (!root.isConnected || !playing) return;
    pos += (now - (last || now)) / 1000;
    last = now;
    if (pos >= TOTAL) { pos = 0; }
    render();
    loop = requestAnimationFrame(tick);
  }
  function setPlay(v) {
    playing = v;
    root.classList.toggle('is-play', v);
    btn.setAttribute('aria-pressed', String(v));
    btn.setAttribute('aria-label', v ? '일시정지' : '재생');
    morph(v ? 1 : 0);
    cancelAnimationFrame(loop);
    if (v) { last = 0; loop = requestAnimationFrame(tick); }
  }
  btn.addEventListener('click', function () { setPlay(!playing); });

  // 파형을 누르거나 끌어서 위치를 옮깁니다. 방향키는 5초씩 움직입니다
  function seek(x) {
    var r = wave.getBoundingClientRect();
    pos = Math.max(0, Math.min(1, (x - r.left) / r.width)) * TOTAL;
    render();
  }
  wave.addEventListener('pointerdown', function (e) { wave.setPointerCapture(e.pointerId); seek(e.clientX); });
  wave.addEventListener('pointermove', function (e) { if (wave.hasPointerCapture(e.pointerId)) seek(e.clientX); });
  wave.addEventListener('keydown', function (e) {
    var d = { ArrowRight: 5, ArrowUp: 5, ArrowLeft: -5, ArrowDown: -5 }[e.key];
    if (e.key === 'Home') d = -TOTAL; if (e.key === 'End') d = TOTAL;
    if (d) { e.preventDefault(); pos = Math.max(0, Math.min(TOTAL - 1, pos + d)); render(); }
  });
  render();
})();

(function () {
  var root = document.currentScript.previousElementSibling;
  var btn = root.querySelector('.u008-btn');
  var cmd = root.querySelector('.u008-cmd');
  var tip = root.querySelector('.u008-tip');
  var tabs = Array.prototype.slice.call(root.querySelectorAll('.u008-tab'));
  var t = 0;
